// ============================================================================
// CS 32 — background-work-queue — ORIGINAL
// ============================================================================
// POST /send accepts an email and answers instantly, because "sending" happens
// in the background. The background is `Task.Run(...)` with the result thrown
// away — the most popular two lines of broken code in .NET.
//
// Run:   dotnet run csharp/32-background-work-queue/original.cs
// Then:  curl -X POST http://localhost:5032/send -H "Content-Type: application/json" -d "{\"to\":\"ada@example.com\",\"subject\":\"hi\"}"
//        curl -X POST http://localhost:5032/send -H "Content-Type: application/json" -d "{\"to\":\"not-an-email\",\"subject\":\"oops\"}"
//        curl http://localhost:5032/status
//
// Watch the second one. The server console prints NOTHING. The request got a
// cheerful 200 {"queued":true}. The exception was thrown, caught by nobody,
// attached to a Task nobody kept, and dropped on the floor when the garbage
// collector got round to it. (Before .NET 4.5 an unobserved task exception at
// least killed the process. Now it is silent by default.)

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

int sent = 0;          // mutated from many thread-pool threads at once. Also a bug.

app.MapPost("/send", (EmailRequest req) =>
{
    // ⚠️ THE BUG, in one character: `_ =`. It means "I have a Task here and I
    // am deliberately not keeping it". Nobody awaits it, so nobody ever learns
    // whether the work succeeded, failed, or ran at all.
    _ = Task.Run(async () =>
    {
        await Task.Delay(500);                        // pretend SMTP is slow

        if (!req.To.Contains('@'))
            throw new InvalidOperationException($"'{req.To}' is not an email address");

        sent++;                                        // two threads, one ++, lost counts
        Console.WriteLine($"[background] sent '{req.Subject}' to {req.To}");
    });

    // A 200 that means "we started something". It cannot mean more than that:
    // there is no id, so the caller can never ask what happened. Ever.
    return Results.Ok(new { queued = true });
});

app.MapGet("/status", () => new { sent });

// ---------------------------------------------------------------------------
// Four ways this hurts, in the order you meet them:
//
// 1. EXCEPTIONS VANISH. The bad-address POST above returns 200 and produces no
//    log line, no alert, nothing. The customer never gets the email and the
//    system's own opinion is that everything is fine.
//
// 2. NO STATUS. `{"queued":true}` is the end of the conversation. Nobody can
//    build a "resend" button, a retry, or a support answer to "did it go?".
//
// 3. WORK IS LOST ON SHUTDOWN. Press Ctrl+C during those 500ms and the email
//    is gone — not delayed, not retried, gone, and unrecorded. Deploys do this
//    to a slice of your traffic every single time.
//
// 4. NO LIMIT. Ten thousand requests start ten thousand concurrent Task.Runs,
//    all fighting for the same thread pool as the requests that are still
//    arriving. The queue that would have smoothed this out does not exist:
//    "the background" is not a place, it is a pile.
// ---------------------------------------------------------------------------

app.Run("http://localhost:5032");

record EmailRequest(string To, string Subject);

# 🏋️ Practice: Background Work Queues

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking. Every one of them is testable without starting the server: that is the point of keeping the domain out of the plumbing.

## Exercises

### ⭐ 1. Put a failure back in the pile (warm-up)

Add `Job Requeue()` to `Job`: `Failed → Queued`, clearing the error but **keeping** `Attempts`, so a retried job remembers how many times it has been tried. Every other state must refuse it.

Practices: adding a transition to a state machine — including the "which states refuse this?" half, which is the half people skip.

Hint: copy `Reject`'s shape. `this with { Status = JobStatus.Queued, Error = null }`, guarded by `Status is JobStatus.Failed`.

Check it offline: add to `Tests.cs` — all should pass:
```csharp
var failed = Job.Queue("j1", "a@b.c", "hi", T0).Start().Fail("smtp down");
var again = failed.Requeue();
Check.Equal(JobStatus.Queued, again.Status, "a failed job can go back in the queue");
Check.Equal(null, again.Error, "the old error is cleared");
Check.Equal(1, again.Attempts, "but the attempt count is NOT — that is how retries end");
Check.Throws<InvalidOperationException>(() => again.Requeue(), "a Queued job is already queued");
Check.Throws<InvalidOperationException>(() => Job.Queue("j2", "a@b.c", "hi", T0).Start().Succeed().Requeue(),
    "and a succeeded job is never retried");
```

### ⭐⭐ 2. Try again, but not forever (core)

Add `JobRunner.RunWithRetriesAsync(JobStore store, WorkItem item, Func<WorkItem, CancellationToken, Task> work, int maxAttempts, CancellationToken ct)`. It runs the job; on failure it requeues and runs again, up to `maxAttempts` times; it stops the moment the work succeeds. The final job state is what it returns.

Practices: composing on top of `RunAsync` instead of duplicating it, and the retry loop every queue eventually grows.

Hint: a `for` loop over the attempts calling `RunAsync`. `if (result is null or { Status: JobStatus.Succeeded }) return result;` covers both exits (a missing job and a success). Requeue only when another attempt is coming — leaving the last failure as `Failed` is the whole point.

Check it offline: add to `Tests.cs` — all should pass (inside the async half):
```csharp
var store = new JobStore(() => T0);
var flaky = store.Add("ada@example.com", "hi");
int calls = 0;
var ok = await JobRunner.RunWithRetriesAsync(store, new WorkItem(flaky.Id, flaky.To, flaky.Subject),
    (i, ct) => { calls++; return calls < 3 ? throw new InvalidOperationException("smtp down") : Task.CompletedTask; },
    maxAttempts: 5, CancellationToken.None);
Check.Equal(JobStatus.Succeeded, ok!.Status, "the third attempt worked");
Check.Equal(3, ok.Attempts, "and the job counted all three");

var doomed = store.Add("nope", "hi");
var dead = await JobRunner.RunWithRetriesAsync(store, new WorkItem(doomed.Id, doomed.To, doomed.Subject),
    (i, ct) => throw new InvalidOperationException("always broken"), maxAttempts: 3, CancellationToken.None);
Check.Equal(JobStatus.Failed, dead!.Status, "hopeless work ends Failed, not requeued forever");
Check.Equal(3, dead.Attempts, "after exactly maxAttempts tries");
Check.Equal("always broken", dead.Error, "with the last error kept");
```

### ⭐⭐ 3. Don't send it twice (core)

Clients retry. If a POST is retried because the response was lost, the customer should not get two emails. Add an idempotency key: `JobStore.AddOrGet(string key, string to, string subject)` returning `(Job Job, bool Created)` — the first call creates the job and remembers the key, later calls with the same key return the *same* job and `Created: false`.

Practices: the idea that makes at-least-once queues survivable, and returning a tuple so the caller can tell "made one" from "found one" (202 vs 200).

Hint: a second `ConcurrentDictionary<string, string>` mapping key → job id. `GetOrAdd` is not enough on its own, because you must not create a job before you know the key is new — look the key up first, then `Add`, then map it.

Check it offline: add to `Tests.cs` — all should pass:
```csharp
var store = new JobStore(() => T0);
var (first, created1) = store.AddOrGet("order-42", "ada@example.com", "receipt");
var (second, created2) = store.AddOrGet("order-42", "ada@example.com", "receipt");
Check.True(created1, "the first call created a job");
Check.Equal(false, created2, "the second call did not");
Check.Equal(first.Id, second.Id, "it returned the SAME job — one email, not two");
Check.Equal(1, store.Count, "and the store holds one job, not two");
var (other, created3) = store.AddOrGet("order-43", "ada@example.com", "receipt");
Check.True(created3, "a different key is a different job");
Check.Equal(2, store.Count, "so now there are two");
```

### ⭐⭐⭐ 4. Work that takes too long (challenge)

A hung SMTP call would park the worker forever, and one stuck item stops the whole queue. Add `JobRunner.WithTimeout(Func<WorkItem, CancellationToken, Task> work, TimeSpan timeout)` — a **decorator** returning a new work function that cancels the inner work after `timeout` and throws `TimeoutException`, so `RunAsync` records it as an ordinary failure.

Practices: `CancellationTokenSource.CreateLinkedTokenSource` + `CancelAfter`, an exception filter that tells "we timed out" apart from "the app is shutting down", and wrapping behaviour instead of editing it.

Hint: link the caller's token so shutdown still cancels, `timer.CancelAfter(timeout)`, then `catch (OperationCanceledException) when (timer.IsCancellationRequested && !ct.IsCancellationRequested) throw new TimeoutException(...)`. The `when` filter is what stops a shutdown being reported as a timeout.

Check it offline: add to `Tests.cs` — all should pass (inside the async half):
```csharp
var store = new JobStore(() => T0);
var slowJob = store.Add("ada@example.com", "hi");
var sw = System.Diagnostics.Stopwatch.StartNew();
var timedOut = await JobRunner.RunAsync(store, new WorkItem(slowJob.Id, slowJob.To, slowJob.Subject),
    JobRunner.WithTimeout((i, ct) => Task.Delay(TimeSpan.FromSeconds(30), ct), TimeSpan.FromMilliseconds(50)),
    CancellationToken.None);
sw.Stop();
Check.Equal(JobStatus.Failed, timedOut!.Status, "a job that hangs is a job that failed");
Check.Equal("work did not finish within 50ms", timedOut.Error, "...with a reason a human can act on");
Check.True(sw.ElapsedMilliseconds < 5000, "and it gave up after 50ms, not 30 seconds");

var quickJob = store.Add("grace@example.com", "hi");
var fine = await JobRunner.RunAsync(store, new WorkItem(quickJob.Id, quickJob.To, quickJob.Subject),
    JobRunner.WithTimeout((i, ct) => Task.CompletedTask, TimeSpan.FromSeconds(5)), CancellationToken.None);
Check.Equal(JobStatus.Succeeded, fine!.Status, "fast work is untouched by the wrapper");
```

### ⭐⭐⭐ 5. Leave nothing unaccounted for (challenge)

On shutdown, whatever is still in the channel is never going to run. Add `JobRunner.DrainAsync(WorkQueue queue, JobStore store, string reason)`: complete the writer so nothing new arrives, read everything that is left, and `Reject` each job with the reason — returning how many were rejected. Then call it from `EmailWorker.StopAsync`.

Practices: `ReadAllAsync` *ending* when a channel is completed (the property that makes clean shutdown possible), and the discipline that every job reaches a final state.

Hint: `queue.CompleteAdding();` then `await foreach (var item in queue.ReadAllAsync(CancellationToken.None))` — with the writer completed, the loop drains what is left and finishes on its own instead of waiting forever. `store.Update(item.JobId, j => j.Reject(reason))` returns null for jobs that are not there, so count only the non-nulls.

Check it offline: add to `Tests.cs` — all should pass (inside the async half):
```csharp
var store = new JobStore(() => T0);
var queue = new WorkQueue(capacity: 10);
var jobs = new[] { store.Add("a@b.c", "1"), store.Add("c@d.e", "2"), store.Add("e@f.g", "3") };
foreach (var j in jobs) queue.TryEnqueue(new WorkItem(j.Id, j.To, j.Subject));
int rejected = await JobRunner.DrainAsync(queue, store, "shutting down");
Check.Equal(3, rejected, "every waiting job was accounted for");
Check.Equal(0, queue.Depth, "and the queue is empty");
Check.Equal(3, store.CountByStatus(JobStatus.Failed), "they are all Failed...");
store.TryGet(jobs[0].Id, out var one);
Check.Equal("shutting down", one!.Error, "...with the reason recorded");
Check.Equal(0, one.Attempts, "and 0 attempts — they never ran, which is different from breaking");
```

## Solutions

### 1. Put a failure back in the pile

```csharp
/// Failed -> Queued. The error is cleared (it is about to be tried again) but
/// Attempts is kept — a retry loop with no memory is an infinite loop.
public Job Requeue() => Status is JobStatus.Failed
    ? this with { Status = JobStatus.Queued, Error = null }
    : throw new InvalidOperationException($"a {Status} job cannot be requeued");
```

WHY: the guard is the interesting half. Without it, requeuing a `Succeeded` job would silently send a second email, and requeuing a `Running` one would let two workers process the same item — bugs that appear under load, at night, once a month. Keeping `Attempts` across the transition is what makes exercise 2 terminate: the counter lives on the job, so it survives the trip through the queue, which a local variable in a retry loop would not.

### 2. Try again, but not forever

```csharp
/// Retry on top of RunAsync, never inside it: the single-attempt logic stays
/// one thing, and the policy (how many, when to stop) stays another.
public static async Task<Job?> RunWithRetriesAsync(
    JobStore store,
    WorkItem item,
    Func<WorkItem, CancellationToken, Task> work,
    int maxAttempts,
    CancellationToken cancellationToken)
{
    Job? result = null;
    for (int attempt = 1; attempt <= maxAttempts; attempt++)
    {
        result = await RunAsync(store, item, work, cancellationToken);

        // Gone, or done: either way there is nothing left to try.
        if (result is null or { Status: JobStatus.Succeeded }) return result;

        // Only put it back if another attempt is actually coming — otherwise
        // the job must be left Failed, which is the honest final state.
        if (attempt < maxAttempts) store.Update(item.JobId, j => j.Requeue());
    }
    return result;
}
```

WHY: building the loop *around* `RunAsync` rather than inside it keeps two decisions separate — "how do I run one attempt and record it" versus "how many attempts are worth making" — so the retry policy can change without touching the code that writes to the store. `result is null or { Status: JobStatus.Succeeded }` is cs#31's patterns doing real work: one line covering "the job vanished" and "we are done". The missing `Requeue` on the last attempt is deliberate and is the kind of off-by-one that would otherwise leave every hopeless job sitting in `Queued` forever, looking like a backlog. Real systems add one thing this does not: a *delay* between attempts (exponential backoff), because retrying a broken mail server three times in three milliseconds is not a retry, it is a stampede.

### 3. Don't send it twice

```csharp
private readonly ConcurrentDictionary<string, string> byKey = new();   // key -> job id

/// Idempotency: the same key always maps to the same job. Created: false
/// tells the endpoint to answer 200 (here it is again) rather than 202
/// (I have taken a new one).
public (Job Job, bool Created) AddOrGet(string key, string to, string subject)
{
    if (byKey.TryGetValue(key, out var existingId) && TryGet(existingId, out var existing))
        return (existing, false);

    var job = Add(to, subject);
    var winnerId = byKey.GetOrAdd(key, job.Id);        // two threads, one winner

    // We lost the race: somebody else's job owns this key, so ours is spare.
    if (winnerId != job.Id && TryGet(winnerId, out var winner))
        return (winner, false);

    return (job, true);
}
```

WHY: `GetOrAdd` is doing the concurrency work — if two identical POSTs arrive at once, both may create a job, but only one can own the key, and the loser hands back the winner's job. (The loser's job is left orphaned in the store, which is a fair trade for keeping the method lock-free; a production version would remove it.) Idempotency keys are how Stripe, and every payment API since, let clients retry safely, and they are the standard partner of an at-least-once queue: the *sender* may repeat, so the *receiver* must be able to recognise a repeat. Notice this is pure domain logic — it needs no HTTP to exist, and no HTTP to test.

### 4. Work that takes too long

```csharp
/// A decorator: same shape in, same shape out, one behaviour added. The inner
/// work is cancelled after `timeout`, and the result is an ordinary exception
/// that RunAsync records like any other failure.
public static Func<WorkItem, CancellationToken, Task> WithTimeout(
    Func<WorkItem, CancellationToken, Task> work, TimeSpan timeout) =>
    async (item, cancellationToken) =>
    {
        // Linked, so BOTH deadlines apply: our timeout and the app's shutdown.
        using var timer = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        timer.CancelAfter(timeout);

        try
        {
            await work(item, timer.Token);
        }
        catch (OperationCanceledException)
            when (timer.IsCancellationRequested && !cancellationToken.IsCancellationRequested)
        {
            // Ours fired, not the app's: this is a timeout, not a shutdown.
            throw new TimeoutException($"work did not finish within {timeout.TotalMilliseconds:0}ms");
        }
    };
```

WHY: three ideas in twelve lines. **Decorating** rather than editing means `RunAsync`, the worker and the tests all stay as they were — `WithTimeout(sender.SendAsync, TimeSpan.FromSeconds(10))` is the only change at the wiring site. **Linked tokens** are how .NET composes deadlines: the inner work is cancelled if *either* the timeout elapses or the app is stopping, and you do not have to choose which. And the **exception filter** (`when`) is what makes the failure message honest — without it, a Ctrl+C during a send would be recorded as "timed out", which is a lie that would send somebody hunting a performance problem that does not exist. Filters run before the stack unwinds and can inspect any state, which is exactly what this needs.

### 5. Leave nothing unaccounted for

```csharp
/// Shutdown, honestly: nothing new gets in, everything already waiting is
/// marked Failed with a reason, and the count is returned so the log can say
/// what happened. Returns when the queue is empty.
public static async Task<int> DrainAsync(WorkQueue queue, JobStore store, string reason)
{
    queue.CompleteAdding();          // ⬅ without this, the loop below never ends

    int rejected = 0;
    await foreach (var item in queue.ReadAllAsync(CancellationToken.None))
        if (store.Update(item.JobId, job => job.Reject(reason)) is not null)
            rejected++;

    return rejected;
}

// EmailWorker.StopAsync, after the base call:
int abandoned = await JobRunner.DrainAsync(queue, store, "shutting down");
if (abandoned > 0) Console.WriteLine($"[worker] recorded {abandoned} job(s) as not-run");
```

WHY: `CompleteAdding()` is load-bearing and the reason this exercise is worth doing. `ReadAllAsync` on an open channel waits forever for the next item — it is *supposed* to — so a drain loop over a channel nobody closed hangs on shutdown, which is the exact bug this project exists to avoid. Completing the writer first turns "wait for more" into "there is no more", and the loop ends by itself. `Reject` (rather than `Fail`) is the right transition because these jobs never ran: `Attempts` stays 0, so afterwards you can tell "we shut down on it" from "it broke", which is the difference between a job you can safely re-run and one you should look at first. The general principle is worth keeping: every job should end in a final state, and "the process exited" is not one of them.

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

// The consumer side: one long-lived worker that pulls items off the channel
// and records what happened to each of them.

/// The bit worth testing: take one work item, walk the job through its states,
/// and make sure a thrown exception ends up WRITTEN DOWN instead of lost.
/// It is a plain static method taking the work as a delegate, so a test can
/// hand it a function that throws and check the resulting job — no host, no
/// HTTP, no waiting.
public static class JobRunner
{
    public static async Task<Job?> RunAsync(
        JobStore store,
        WorkItem item,
        Func<WorkItem, CancellationToken, Task> work,
        CancellationToken cancellationToken)
    {
        var running = store.Update(item.JobId, job => job.Start());
        if (running is null) return null;          // the job is not in the store

        try
        {
            await work(item, cancellationToken);
            return store.Update(item.JobId, job => job.Succeed());
        }
        catch (Exception ex)
        {
            // THE LINE THE ORIGINAL DID NOT HAVE. Catching everything is
            // usually a smell; in a worker loop it is the job description —
            // one poisoned item must not take the queue down with it.
            return store.Update(item.JobId, job => job.Fail(ex.Message));
        }
    }
}

/// Sending, behind an interface so the worker can be pointed at a fake in
/// tests and at SMTP in production (cs#18's dependency injection).
public interface IEmailSender
{
    Task SendAsync(WorkItem item, CancellationToken cancellationToken);
}

/// The stand-in for a mail server: slow, and picky about addresses.
public sealed class FakeSmtpSender : IEmailSender
{
    public async Task SendAsync(WorkItem item, CancellationToken cancellationToken)
    {
        await Task.Delay(500, cancellationToken);          // pretend SMTP is slow

        if (!EmailAddress.LooksValid(item.To))
            throw new InvalidOperationException($"'{item.To}' is not an email address");

        Console.WriteLine($"[worker] sent '{item.Subject}' to {item.To} (job {item.JobId})");
    }
}

/// `BackgroundService` is the base class for a hosted service: the host starts
/// ExecuteAsync when the app starts and waits for it to finish when the app
/// stops. Registered with AddHostedService — no package needed, it lives in
/// the shared framework next to ASP.NET Core itself.
public sealed class EmailWorker : BackgroundService
{
    private readonly WorkQueue queue;
    private readonly JobStore store;
    private readonly IEmailSender sender;

    public EmailWorker(WorkQueue queue, JobStore store, IEmailSender sender)
        => (this.queue, this.store, this.sender) = (queue, store, sender);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("[worker] started, waiting for work");

        try
        {
            // One item at a time, forever. `await foreach` parks the worker with
            // no thread of its own while the queue is empty — this loop costs
            // nothing when there is nothing to do.
            await foreach (var item in queue.ReadAllAsync(stoppingToken))
            {
                var finished = await JobRunner.RunAsync(store, item, sender.SendAsync, stoppingToken);
                if (finished is { Status: JobStatus.Failed })
                    Console.WriteLine($"[worker] job {finished.Id} FAILED: {finished.Error}");
            }
        }
        catch (OperationCanceledException)
        {
            // Shutdown. Note what does NOT happen here: nothing is lost in
            // silence. Anything still Queued is still in the store, visible on
            // GET /jobs, waiting to be re-queued by a restart or an operator.
            Console.WriteLine("[worker] shutdown requested, stopping");
        }

        Console.WriteLine($"[worker] stopped. {store.CountByStatus(JobStatus.Queued)} job(s) never got a turn.");
    }

    /// Called by the host when the app is stopping, BEFORE it waits for
    /// ExecuteAsync. Completing the writer means "no new work" so the loop can
    /// drain what is already queued and end by itself.
    public override async Task StopAsync(CancellationToken cancellationToken)
    {
        queue.CompleteAdding();
        await base.StopAsync(cancellationToken);
    }
}

// The domain: what a job IS, and which moves are legal. No HTTP, no channel,
// no clock — which is why every rule below is pinned by a one-line test.

public enum JobStatus { Queued, Running, Succeeded, Failed }

/// One unit of background work and everything anyone will ever want to know
/// about it. A record, so every transition RETURNS A NEW STATE instead of
/// mutating one that another thread may be reading (cs#07, cs#02).
public sealed record Job(
    string Id,
    string To,
    string Subject,
    JobStatus Status,
    string? Error,
    int Attempts,
    DateTimeOffset QueuedAt)
{
    public static Job Queue(string id, string to, string subject, DateTimeOffset queuedAt) =>
        new(id, to, subject, JobStatus.Queued, Error: null, Attempts: 0, queuedAt);

    /// Queued -> Running. The guard is the point: a job that is already running
    /// (or finished) must never be started again, and saying so HERE means no
    /// caller can forget. The original had no states at all, so it had no rules
    /// to break — and no way to answer "what happened?".
    public Job Start() => Status is JobStatus.Queued
        ? this with { Status = JobStatus.Running, Attempts = Attempts + 1 }
        : throw new InvalidOperationException($"a {Status} job cannot be started");

    /// Running -> Succeeded.
    public Job Succeed() => Status is JobStatus.Running
        ? this with { Status = JobStatus.Succeeded, Error = null }
        : throw new InvalidOperationException($"a {Status} job cannot succeed");

    /// Running -> Failed, WITH a reason. A failure with no reason is how the
    /// original's silence gets re-invented, so the type refuses to store one.
    public Job Fail(string error) => (Status, string.IsNullOrWhiteSpace(error)) switch
    {
        (JobStatus.Running, false) => this with { Status = JobStatus.Failed, Error = error },
        (JobStatus.Running, true) => throw new ArgumentException("a failure needs a reason", nameof(error)),
        _ => throw new InvalidOperationException($"a {Status} job cannot fail"),
    };

    /// Queued -> Failed, without ever running: the queue was full, the address
    /// was refused, the host is shutting down. Attempts stays 0, which is how
    /// you later tell "tried and broke" from "never got a turn".
    public Job Reject(string reason) => Status is JobStatus.Queued
        ? this with { Status = JobStatus.Failed, Error = reason }
        : throw new InvalidOperationException($"a {Status} job cannot be rejected");

    public bool IsFinished => Status is JobStatus.Succeeded or JobStatus.Failed;
}

/// What the endpoint accepts, kept separate from what the system stores —
/// a client may not invent its own job id or status (cs#17's lesson).
public sealed record EmailRequest(string? To, string? Subject);

/// The message that travels through the channel. Deliberately small: an id and
/// the facts the worker needs. Passing whole objects through a queue is how
/// queues start holding memory they cannot let go of.
public sealed record WorkItem(string JobId, string To, string Subject);

public static class EmailAddress
{
    /// Not a validator — a smoke test. Real address validation is a swamp;
    /// what matters here is that the rule is a pure function with tests, not a
    /// `req.To.Contains('@')` buried in a lambda nobody can reach.
    public static bool LooksValid(string? address)
    {
        if (string.IsNullOrWhiteSpace(address)) return false;
        int at = address.IndexOf('@');
        return at > 0                            // something before the @
            && at == address.LastIndexOf('@')    // exactly one @
            && at < address.Length - 1           // something after it
            && !address.Contains(' ');           // and no spaces anywhere
    }
}

using System.Collections.Concurrent;
using System.Diagnostics.CodeAnalysis;

// Where job states live. In-memory on purpose: swapping this for a table or a
// Redis hash is a change of one class (cs#21's repository idea), and none of
// the rules in Jobs.cs would notice.
//
// It is a SINGLETON shared by the web endpoints and the background worker, so
// every method has to be safe to call from several threads at once —
// ConcurrentDictionary plus immutable records does that without a single lock.
public sealed class JobStore
{
    private readonly ConcurrentDictionary<string, Job> jobs = new();
    private readonly Func<DateTimeOffset> clock;

    public JobStore(Func<DateTimeOffset>? clock = null)
        => this.clock = clock ?? (() => DateTimeOffset.UtcNow);   // injected time, so tests are instant

    public int Count => jobs.Count;

    /// Create a Queued job and remember it. The id is ours to mint: handing the
    /// caller an id is the entire difference between this and the original's
    /// `{"queued": true}`.
    public Job Add(string to, string subject, string? id = null)
    {
        var job = Job.Queue(id ?? NewId(), to, subject, clock());
        if (!jobs.TryAdd(job.Id, job))
            throw new InvalidOperationException($"job '{job.Id}' already exists");
        return job;
    }

    public bool TryGet(string id, [MaybeNullWhen(false)] out Job job) => jobs.TryGetValue(id, out job);

    /// Apply a transition from Jobs.cs to the stored state.
    ///
    /// The loop is optimistic concurrency: read the current state, compute the
    /// next one, and swap it in ONLY IF nobody else changed it meanwhile
    /// (TryUpdate compares against `current`). If they did, try again with what
    /// is there now. Returns null when the id is unknown.
    public Job? Update(string id, Func<Job, Job> transition)
    {
        while (jobs.TryGetValue(id, out var current))
        {
            var next = transition(current);
            if (jobs.TryUpdate(id, next, current)) return next;
        }
        return null;
    }

    /// A snapshot, newest first. Copying is deliberate: callers get a list that
    /// cannot change under them while they are iterating it.
    public IReadOnlyList<Job> All() =>
        jobs.Values.OrderByDescending(j => j.QueuedAt).ThenBy(j => j.Id, StringComparer.Ordinal).ToList();

    public int CountByStatus(JobStatus status) => jobs.Values.Count(j => j.Status == status);

    /// 12 hex characters: short enough to paste into a curl, long enough that
    /// two of them will not collide before the heat death of the sprint.
    public static string NewId() => Guid.NewGuid().ToString("N")[..12];
}

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

// Program.cs — accept work, hand it to a queue, tell the caller where to look.
// The endpoints do no work at all: POST writes one item to a channel and
// returns an id. The worker in EmailWorker.cs does the rest, and writes down
// what happened either way.
//
// Run:   dotnet run --project csharp/32-background-work-queue/refactored
// Test:  dotnet run --project csharp/32-background-work-queue/refactored -- test

var builder = WebApplication.CreateBuilder(args);

// One store and one queue for the whole app: the endpoints write to them, the
// worker reads from them, and the DI container is what introduces the two.
builder.Services.AddSingleton<JobStore>();
builder.Services.AddSingleton(new WorkQueue(capacity: 100));
builder.Services.AddSingleton<IEmailSender, FakeSmtpSender>();

// AddHostedService = "start this when the app starts, stop it when the app
// stops, and WAIT for it to finish stopping". That last clause is the whole
// difference from Task.Run: shutdown is something the worker takes part in.
builder.Services.AddHostedService<EmailWorker>();

var app = builder.Build();

// POST /jobs -> 202 Accepted + an id. 202 is the honest status code for "I
// have not done this yet": it means accepted for processing, and the Location
// header says where to watch it. (The original returned 200 — "done" — for
// work that had not started.)
app.MapPost("/jobs", (EmailRequest req, JobStore store, WorkQueue queue) =>
{
    if (string.IsNullOrWhiteSpace(req.To))
        return Results.BadRequest(new { error = "to is required" });

    // Note we do NOT check the address here, on purpose: leaving one bad
    // address to fail inside the worker is how the demo shows a failure being
    // recorded. A real API would validate at the edge as well (cs#17).
    var job = store.Add(req.To.Trim(), string.IsNullOrWhiteSpace(req.Subject) ? "(no subject)" : req.Subject.Trim());

    if (!queue.TryEnqueue(new WorkItem(job.Id, job.To, job.Subject)))
    {
        // The queue is full. Say so, record it, and let the caller retry —
        // instead of quietly starting a 101st concurrent Task.
        var rejected = store.Update(job.Id, j => j.Reject("queue full"));
        return Results.Json(new { id = job.Id, status = rejected?.Status.ToString(), error = "queue full, retry shortly" },
            statusCode: StatusCodes.Status503ServiceUnavailable);
    }

    return Results.Accepted($"/jobs/{job.Id}", View(job));
});

// GET /jobs/{id} -> the answer to "did it go?", which the original could
// never give.
app.MapGet("/jobs/{id}", (string id, JobStore store) =>
    store.TryGet(id, out var job)
        ? Results.Ok(View(job))
        : Results.NotFound(new { error = $"no job '{id}'" }));

app.MapGet("/jobs", (JobStore store) => store.All().Select(View));

app.MapGet("/stats", (JobStore store, WorkQueue queue) => new
{
    queueDepth = queue.Depth,
    queueCapacity = queue.Capacity,
    total = store.Count,
    queued = store.CountByStatus(JobStatus.Queued),
    running = store.CountByStatus(JobStatus.Running),
    succeeded = store.CountByStatus(JobStatus.Succeeded),
    failed = store.CountByStatus(JobStatus.Failed),
});

app.Run("http://localhost:5032");

// The wire shape of a job: the enum spelled out, so clients read "Succeeded"
// instead of guessing what 2 means.
static object View(Job job) => new
{
    id = job.Id,
    to = job.To,
    subject = job.Subject,
    status = job.Status.ToString(),
    error = job.Error,
    attempts = job.Attempts,
    queuedAt = job.QueuedAt,
};

// Tests.cs — the whole background system, tested without starting a server,
// a thread, or a mail client. That is the payoff of pulling the domain (job
// states, the store, the queue, the run-one-item loop) out of the plumbing:
// the interesting behaviour is reachable from an ordinary method call.
public static class Tests
{
    private static readonly DateTimeOffset T0 = new(2026, 1, 1, 9, 0, 0, TimeSpan.Zero);

    public static int Run()
    {
        Console.WriteLine("the job state machine");
        var queued = Job.Queue("j1", "ada@example.com", "hello", T0);
        Check.Equal(JobStatus.Queued, queued.Status, "a new job starts Queued");
        Check.Equal(0, queued.Attempts, "and has not been attempted");
        Check.Equal(false, queued.IsFinished, "Queued is not a finished state");

        var running = queued.Start();
        Check.Equal(JobStatus.Running, running.Status, "Queued -> Running");
        Check.Equal(1, running.Attempts, "starting counts as an attempt");
        Check.Equal(JobStatus.Queued, queued.Status, "...and the old value is untouched — transitions RETURN a new job");

        var done = running.Succeed();
        Check.Equal(JobStatus.Succeeded, done.Status, "Running -> Succeeded");
        Check.Equal(null, done.Error, "a success carries no error");
        Check.True(done.IsFinished, "Succeeded is a finished state");

        var failed = running.Fail("smtp said no");
        Check.Equal(JobStatus.Failed, failed.Status, "Running -> Failed");
        Check.Equal("smtp said no", failed.Error, "and the reason is kept — the original's vanished");
        Check.True(failed.IsFinished, "Failed is a finished state too");

        var rejected = queued.Reject("queue full");
        Check.Equal(JobStatus.Failed, rejected.Status, "Queued -> Failed without running (rejected)");
        Check.Equal(0, rejected.Attempts, "a rejected job was never attempted — that is how you tell them apart");

        Console.WriteLine("...and the moves it refuses");
        Check.Throws<InvalidOperationException>(() => running.Start(), "a Running job cannot start again");
        Check.Throws<InvalidOperationException>(() => done.Start(), "a finished job cannot be restarted");
        Check.Throws<InvalidOperationException>(() => queued.Succeed(), "a Queued job cannot succeed — it never ran");
        Check.Throws<InvalidOperationException>(() => queued.Fail("nope"), "a Queued job cannot fail — use Reject");
        Check.Throws<InvalidOperationException>(() => done.Fail("too late"), "a Succeeded job cannot fail afterwards");
        Check.Throws<InvalidOperationException>(() => running.Reject("nope"), "a Running job cannot be rejected");
        Check.Throws<ArgumentException>(() => running.Fail("   "), "a failure with no reason is refused");

        Console.WriteLine("the store");
        var now = T0;
        var store = new JobStore(() => now);
        var a = store.Add("ada@example.com", "hi");
        Check.Equal(JobStatus.Queued, a.Status, "Add stores a Queued job");
        Check.Equal(12, a.Id.Length, "and mints a short id — the thing the caller gets back");
        Check.Equal(T0, a.QueuedAt, "the clock is injected, so this is not a guess");
        Check.True(store.TryGet(a.Id, out var found) && found.To == "ada@example.com", "TryGet finds it");
        Check.Equal(false, store.TryGet("nope", out _), "TryGet reports a miss instead of throwing");
        Check.Throws<InvalidOperationException>(() => store.Add("x@y.z", "dup", a.Id), "two jobs cannot share an id");

        var started = store.Update(a.Id, j => j.Start());
        Check.Equal(JobStatus.Running, started!.Status, "Update applies a transition");
        Check.True(store.TryGet(a.Id, out var reread) && reread.Status == JobStatus.Running, "...and the store kept it");
        Check.Equal(null, store.Update("nope", j => j.Start()), "updating an unknown id returns null, not an exception");
        Check.Equal(1, store.Count, "the store holds one job");

        now = T0.AddMinutes(1);
        var b = store.Add("grace@example.com", "later");
        Check.Equal(2, store.Count, "two jobs now");
        Check.Equal(b.Id, store.All()[0].Id, "All() is newest first");
        Check.Equal(1, store.CountByStatus(JobStatus.Running), "CountByStatus sees the running one");
        Check.Equal(1, store.CountByStatus(JobStatus.Queued), "...and the queued one");
        Check.Equal(0, store.CountByStatus(JobStatus.Failed), "and nothing has failed");

        Console.WriteLine("address rules");
        Check.True(EmailAddress.LooksValid("ada@example.com"), "an ordinary address passes");
        Check.Equal(false, EmailAddress.LooksValid("not-an-email"), "no @, no pass");
        Check.Equal(false, EmailAddress.LooksValid("@example.com"), "nothing before the @");
        Check.Equal(false, EmailAddress.LooksValid("ada@"), "nothing after the @");
        Check.Equal(false, EmailAddress.LooksValid("a@b@c.com"), "two @s is not an address");
        Check.Equal(false, EmailAddress.LooksValid("ada lovelace@example.com"), "no spaces");
        Check.Equal(false, EmailAddress.LooksValid(""), "empty is not an address");
        Check.Equal(false, EmailAddress.LooksValid(null), "and neither is null");

        RunAsyncChecks().GetAwaiter().GetResult();   // Check has no async flavour; block once, here

        return Check.Summary();
    }

    private static async Task RunAsyncChecks()
    {
        Console.WriteLine("the channel, exercised through its own reader and writer");
        var queue = new WorkQueue(capacity: 3);
        Check.Equal(0, queue.Depth, "a new queue is empty");
        Check.True(queue.TryEnqueue(new WorkItem("j1", "a@b.c", "one")), "enqueue succeeds while there is room");
        queue.TryEnqueue(new WorkItem("j2", "a@b.c", "two"));
        queue.TryEnqueue(new WorkItem("j3", "a@b.c", "three"));
        Check.Equal(3, queue.Depth, "the queue reports its depth");
        Check.Equal(false, queue.TryEnqueue(new WorkItem("j4", "a@b.c", "four")),
            "a FULL bounded queue says no — backpressure instead of an unbounded pile");

        var first = await queue.Reader.ReadAsync();
        Check.Equal("j1", first.JobId, "items come out in the order they went in (FIFO)");
        Check.Equal("one", first.Subject, "...with their payload intact — a channel round trip");
        Check.Equal(2, queue.Depth, "and the queue shrank");
        Check.True(queue.TryEnqueue(new WorkItem("j4", "a@b.c", "four")), "which makes room for the item that was refused");

        queue.CompleteAdding();
        Check.Equal(false, queue.TryEnqueue(new WorkItem("j5", "a@b.c", "five")), "a completed queue accepts nothing new");
        var drained = new List<string>();
        await foreach (var item in queue.ReadAllAsync(CancellationToken.None))
            drained.Add(item.JobId);
        Check.Equal("j2,j3,j4", string.Join(",", drained),
            "ReadAllAsync drains what is left and then ENDS — that is what makes a clean shutdown possible");

        Console.WriteLine("running one item: what the original could not do");
        var now = T0;
        var store = new JobStore(() => now);
        var good = store.Add("ada@example.com", "hi");
        int workRuns = 0;
        var afterSuccess = await JobRunner.RunAsync(store, new WorkItem(good.Id, good.To, good.Subject),
            (item, ct) => { workRuns++; return Task.CompletedTask; }, CancellationToken.None);
        Check.Equal(JobStatus.Succeeded, afterSuccess!.Status, "work that finishes marks the job Succeeded");
        Check.Equal(1, afterSuccess.Attempts, "one attempt");
        Check.Equal(1, workRuns, "the work ran exactly once");
        Check.True(store.TryGet(good.Id, out var storedGood) && storedGood.Status == JobStatus.Succeeded,
            "and the store — the thing GET /jobs/{id} reads — agrees");

        var bad = store.Add("not-an-email", "oops");
        var afterFailure = await JobRunner.RunAsync(store, new WorkItem(bad.Id, bad.To, bad.Subject),
            (item, ct) => throw new InvalidOperationException($"'{item.To}' is not an email address"),
            CancellationToken.None);
        Check.Equal(JobStatus.Failed, afterFailure!.Status, "work that throws marks the job Failed");
        Check.Equal("'not-an-email' is not an email address", afterFailure.Error,
            "and the exception message is WRITTEN DOWN — in the original it was swallowed whole");
        Check.True(store.TryGet(bad.Id, out var storedBad) && storedBad.Error is not null,
            "the failure survives in the store, ready to be served or retried");
        Check.Equal(1, store.CountByStatus(JobStatus.Failed), "one failure on the books");

        var ghost = await JobRunner.RunAsync(store, new WorkItem("missing", "a@b.c", "x"),
            (item, ct) => Task.CompletedTask, CancellationToken.None);
        Check.Equal(null, ghost, "an item whose job is not in the store is skipped, not crashed on");

        Console.WriteLine("the real sender, without a mail server");
        var sender = new FakeSmtpSender();
        var senderStore = new JobStore(() => now);
        var real = senderStore.Add("grace@example.com", "hello");
        var sent = await JobRunner.RunAsync(senderStore, new WorkItem(real.Id, real.To, real.Subject),
            sender.SendAsync, CancellationToken.None);
        Check.Equal(JobStatus.Succeeded, sent!.Status, "a good address goes through the real send path");
        var refused = senderStore.Add("nope", "hello");
        var refusedResult = await JobRunner.RunAsync(senderStore, new WorkItem(refused.Id, refused.To, refused.Subject),
            sender.SendAsync, CancellationToken.None);
        Check.Equal(JobStatus.Failed, refusedResult!.Status, "a bad one fails...");
        Check.Equal("'nope' is not an email address", refusedResult.Error, "...loudly, and on the record");
    }
}

using System.Threading.Channels;

// The queue itself. `Channel<T>` is .NET's built-in async producer/consumer
// pipe — part of the shared framework, no package to install. Think of it as
// an async `BlockingCollection`, or as a Go channel with C# spelling.
//
// Writers (the endpoints) and readers (the worker) never touch each other:
// one side writes, the other awaits. That is what makes the handoff safe
// without a single `lock`.
public sealed class WorkQueue
{
    private readonly Channel<WorkItem> channel;

    public WorkQueue(int capacity = 100)
    {
        if (capacity < 1) throw new ArgumentOutOfRangeException(nameof(capacity), "capacity must be at least 1");

        // BOUNDED, on purpose. An unbounded queue is the original's "pile of
        // Task.Runs" with extra steps: it absorbs a flood by eating memory
        // until the process dies. A bounded one runs out of room and SAYS so,
        // which is a decision the caller can act on (we answer 503).
        channel = Channel.CreateBounded<WorkItem>(new BoundedChannelOptions(capacity)
        {
            FullMode = BoundedChannelFullMode.Wait,   // TryWrite reports false rather than dropping
            SingleReader = true,                      // one worker drains it
            SingleWriter = false,                     // many requests fill it
        });

        Capacity = capacity;
    }

    public int Capacity { get; }

    /// How many items are waiting. The number you put on a dashboard, and the
    /// one the original could not have computed at all.
    public int Depth => channel.Reader.Count;

    /// Non-blocking enqueue: false means "full, try later". Backpressure is a
    /// feature — it moves the overload from your memory to the caller's retry.
    public bool TryEnqueue(WorkItem item) => channel.Writer.TryWrite(item);

    /// The worker's side: an async stream that yields items as they arrive and
    /// ENDS when the writer is completed and the queue is drained.
    public IAsyncEnumerable<WorkItem> ReadAllAsync(CancellationToken cancellationToken) =>
        channel.Reader.ReadAllAsync(cancellationToken);

    /// "No more work will be added." Called on shutdown so the worker's loop
    /// can finish the items already queued and then exit by itself, instead of
    /// being cut off mid-item.
    public void CompleteAdding() => channel.Writer.TryComplete();

    /// Direct reader access, for tests that want to pull one item without
    /// starting a host. (The worker uses ReadAllAsync; this is the same pipe.)
    public ChannelReader<WorkItem> Reader => channel.Reader;
}
